"""Position windows over invoices."""


def due_between(invoices, low, high):
    """Return the due of the invoices at positions low to high, both included. Positions start at 1."""
    return [x.due for x in invoices[low - 1:high - 1]]


def first_dues(invoices, n):
    """Return the due of the first n invoices."""
    return due_between(invoices, 1, n)


def group_by_client(invoices):
    """Return a dict from client to the list of invoices with that client."""
    groups = {}
    for x in invoices:
        groups.setdefault(x.client, []).append(x)
    return groups


def client_names(invoices):
    """Return the distinct client values, in first-seen order."""
    names = []
    for x in invoices:
        if x.client not in names:
            names.append(x.client)
    return names

